# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM DAVETİNDE SAHABENİN ROLÜ: TEBLİĞ, DAVET VE İRŞAT</text>\n  <rect x="25" y="46" width="315" height="196" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Temel Kavramlar</text>\n  <text x="42" y="96" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Tebliğ:</tspan> İlahi mesajları eksiksiz ve açıkça</text>\n  <text x="50" y="112" font-size="11" fill="#1e3a8a">insanlara ulaştırmak (bildirmek).</text>\n  <text x="42" y="136" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Davet:</tspan> İnsanları güzel söz ve hikmetle</text>\n  <text x="50" y="152" font-size="11" fill="#1e3a8a">İslam\'ı yaşamaya çağırmak (Nahl, 125).</text>\n  <text x="42" y="176" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">İrşat:</tspan> Doğru yolu göstermek, kalpleri</text>\n  <text x="50" y="192" font-size="11" fill="#1e3a8a">aydınlatıp rehberlik etmek.</text>\n  <rect x="42" y="204" width="280" height="28" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="182" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">İlk tebliğ merkezi: Dârü\'l-Erkam (Mekke)</text>\n  <rect x="360" y="46" width="315" height="196" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Sahabenin Katkı Sağladığı Alanlar</text>\n  <rect x="378" y="84" width="280" height="44" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="388" y="102" font-size="11" font-weight="bold" fill="#15803d">1. Eğitim ve İlim (Ashâb-ı Suffe)</text>\n  <text x="388" y="118" font-size="10.5" fill="#14532d">Kur\'an ve sünneti öğrenip kabilelere muallim oldular</text>\n  <rect x="378" y="136" width="280" height="44" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="388" y="154" font-size="11" font-weight="bold" fill="#15803d">2. Diplomasi ve Elçilik</text>\n  <text x="388" y="170" font-size="10.5" fill="#14532d">Hükümdarlara İslam\'a davet mektuplarını ulaştırdılar</text>\n  <rect x="378" y="188" width="280" height="44" rx="6" fill="#ffffff" stroke="#4ade80"/>\n  <text x="388" y="206" font-size="11" font-weight="bold" fill="#15803d">3. Sosyal, Ekonomik ve Askerî Fedakârlık</text>\n  <text x="388" y="222" font-size="10.5" fill="#14532d">Mallarıyla (infak) ve canlarıyla İslam\'ı savundular</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM DAVETİNİN ÖNCÜ ELÇİ VE MUALLİM SAHABİLERİ</text>\n  <rect x="22" y="48" width="210" height="192" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="127" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">Mus\'ab bin Umeyr (r.a.)</text>\n  <text x="34" y="96" font-size="10.5" fill="#78350f">• İslam\'ın <tspan font-weight="bold">ilk muallimi (öğretmeni)</tspan>.</text>\n  <text x="34" y="116" font-size="10.5" fill="#78350f">• I. Akabe Biatı sonrası Medine\'ye</text>\n  <text x="42" y="130" font-size="10.5" fill="#78350f">gönderildi; tatlı diliyle Medine\'yi</text>\n  <text x="42" y="144" font-size="10.5" fill="#78350f">Hicret\'e hazırladı.</text>\n  <text x="34" y="166" font-size="10.5" fill="#78350f">• Uhud Savaşı\'nda sancaktar iken</text>\n  <text x="42" y="180" font-size="10.5" fill="#78350f">şehit düştü.</text>\n  <rect x="34" y="196" width="186" height="32" rx="6" fill="#ffffff" stroke="#f59e0b"/>\n  <text x="127" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">Servetini imanı için feda eden genç</text>\n  <rect x="245" y="48" width="210" height="192" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">Ca\'fer bin Ebî Tâlib (r.a.)</text>\n  <text x="257" y="96" font-size="10.5" fill="#581c87">• <tspan font-weight="bold">Habeşistan hicreti</tspan> kafilesinin</text>\n  <text x="265" y="110" font-size="10.5" fill="#581c87">sözcüsü ve başkanı.</text>\n  <text x="257" y="130" font-size="10.5" fill="#581c87">• Habeş Kralı <tspan font-weight="bold">Necaşi</tspan> huzurunda</text>\n  <text x="265" y="144" font-size="10.5" fill="#581c87"><tspan font-weight="bold">Meryem suresini</tspan> okuyarak</text>\n  <text x="265" y="158" font-size="10.5" fill="#581c87">İslam\'ı en beliğ şekilde tanıttı.</text>\n  <text x="257" y="178" font-size="10.5" fill="#581c87">• Mûte Savaşı\'nda şehit oldu.</text>\n  <rect x="257" y="196" width="186" height="32" rx="6" fill="#ffffff" stroke="#c084fc"/>\n  <text x="350" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#7e22ce">Lakabı: Ca\'fer-i Tayyâr / Ebu\'l-Mesâkîn</text>\n  <rect x="468" y="48" width="210" height="192" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="573" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">Muâz bin Cebel (r.a.)</text>\n  <text x="480" y="96" font-size="10.5" fill="#1e3a8a">• Helal ve haramı en iyi bilen</text>\n  <text x="488" y="110" font-size="10.5" fill="#1e3a8a">âlim ve fakih sahabi.</text>\n  <text x="480" y="130" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Yemen\'e</tspan> kadı (hâkim) ve</text>\n  <text x="488" y="144" font-size="10.5" fill="#1e3a8a">muallim olarak gönderildi.</text>\n  <text x="480" y="164" font-size="10.5" fill="#1e3a8a">• Hüküm sırası: <tspan font-weight="bold">Kur\'an → Sünnet</tspan></text>\n  <text x="488" y="178" font-size="10.5" fill="#1e3a8a"><tspan font-weight="bold">→ İçtihat (Kıyas)</tspan>.</text>\n  <rect x="480" y="196" width="186" height="32" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="573" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">"Kolaylaştırınız, zorlaştırmayınız!"</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SOSYAL, EKONOMİK VE İLMÎ ALANDA SAHABE FEDAKÂRLIĞI</text>\n  <rect x="25" y="48" width="315" height="192" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">İlk Davet Halkası ve Kadın Sahabiler</text>\n  <text x="40" y="96" font-size="11" fill="#14532d">• <tspan font-weight="bold">Hz. Hatice (r.a.):</tspan> İlk inanan; malı ve canıyla</text>\n  <text x="48" y="112" font-size="11" fill="#14532d">Hz. Peygamber\'in en büyük destekçisi.</text>\n  <text x="40" y="134" font-size="11" fill="#14532d">• <tspan font-weight="bold">Hz. Ebû Bekir (r.a.):</tspan> Davetiyle Hz. Osman, Talha,</text>\n  <text x="48" y="150" font-size="11" fill="#14532d">Zübeyr, Sa\'d b. Ebî Vakkas, Abdurrahman b. Avf</text>\n  <text x="48" y="166" font-size="11" fill="#14532d">gibi öncü sahabilerin Müslüman olmasını sağladı.</text>\n  <text x="40" y="188" font-size="11" fill="#14532d">• <tspan font-weight="bold">Hz. Âişe ve Ümmü Seleme:</tspan> Kadınların eğitimi,</text>\n  <text x="48" y="204" font-size="11" fill="#14532d">hadis rivayeti ve fıkıh bilgisinin aktarımı.</text>\n  <text x="40" y="224" font-size="11" font-weight="bold" fill="#15803d">• <tspan font-weight="bold">Nesîbe Hatun (Ümmü Umâre):</tspan> Uhud kahramanı</text>\n  <rect x="360" y="48" width="315" height="192" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="517" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Ekonomik ve İlmî Fedakârlık Örnekleri</text>\n  <rect x="378" y="84" width="280" height="44" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="388" y="101" font-size="11" font-weight="bold" fill="#1e3a8a">Rûme Kuyusu ve Ceyşü\'l-Usre (Hz. Osman)</text>\n  <text x="388" y="117" font-size="10.5" fill="#1e40af">Medine\'nin su ihtiyacını ve Tebük ordusunu donattı</text>\n  <rect x="378" y="136" width="280" height="44" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="388" y="153" font-size="11" font-weight="bold" fill="#1e3a8a">Bi\'r-i Maûne ve Recî\' Şehitleri (Kurrâ Hafızlar)</text>\n  <text x="388" y="169" font-size="10.5" fill="#1e40af">İslam\'ı öğretmeye giderken şehit düşen muallimler</text>\n  <rect x="378" y="188" width="280" height="44" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="388" y="205" font-size="11" font-weight="bold" fill="#1e3a8a">Dıhye el-Kelbî ve Abdullah b. Huzâfe</text>\n  <text x="388" y="221" font-size="10.5" fill="#1e40af">Bizans (Heraklius) ve İran\'a (Kisrâ) giden elçiler</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
